import{_ as o,a0 as d,w as s,s as p,I as t,x as e,a1 as r,A as i,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const G=JSON.parse('{"title":"Linux下的四大下載管理器 | LCTT x X-CMD","titleTemplate":false,"description":"Linux下的四大下載管理器 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux下的四大下載管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux下的四大下載管理器 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20140819 Top 4 Linux download managers","title":"Linux下的四大下載管理器","tag":"201502","desc":""},"relativePath":"201502/20140819 Top 4 Linux download managers.md","filePath":"[post].md"}'),h={name:"201502/20140819 Top 4 Linux download managers.md"},u={id:"uget",tabindex:"-1"},m={id:"kget",tabindex:"-1"},f={id:"downthemall",tabindex:"-1"},x={id:"steadyflow",tabindex:"-1"};function b(T,a,w,k,P,g){const l=d("Link");return s(),p("div",null,[a[23]||(a[23]=t("h1",{id:"linux下的四大下載管理器",tabindex:"-1"},[e("Linux下的四大下載管理器 "),t("a",{class:"header-anchor",href:"#linux下的四大下載管理器","aria-label":"Permalink to “Linux下的四大下載管理器”"},"​")],-1)),a[24]||(a[24]=t("p",null,[t("strong",null,"改善你的網頁下載，以便更好的管理文件鏡像、批量下載還是僅僅希望更好的管理你的文件。")],-1)),a[25]||(a[25]=t("p",null,"下載管理器現在似乎已經不新鮮了，但是他們仍然非常有用。我們來比較一下Linux上排名前四的下載管理器。",-1)),t("h3",u,[r(l,{href:"http://bit.ly/1mx4Uwz"},{default:i(()=>[...a[0]||(a[0]=[e("uGet",-1)])]),_:1}),a[1]||(a[1]=e()),a[2]||(a[2]=t("a",{class:"header-anchor",href:"#uget","aria-label":"Permalink to “uGet”"},"​",-1))]),a[26]||(a[26]=n('<p>如同很多其他的Linux應用一樣，uGet把體積輕巧和功能全面作為宣傳亮點。它能處理多線程下載，支持過濾器，還能與任何網絡瀏覽器進行整合。它從當初的UrlGet開始，如今已經經過了十年。它還能在Windows上運行。</p><p><img src="http://www.linuxuser.co.uk/wp-content/uploads/2014/08/uget1.png" alt="uGet is actually very full-featured, with a lot of the kind of functions that advanced torrent clients use"></p><p><em>uGet的功能其實非常全面，有很多先進的BT下載客户端所擁有的功能</em></p><h4 id="界面" tabindex="-1">界面 <a class="header-anchor" href="#界面" aria-label="Permalink to “界面”">​</a></h4><p>uGet讓我們想起了許多BT下載客户端的界面：有着活躍、結束、暫停等等對於不同下載任務的分類。儘管有很多的信息，但是他們都以非常簡單明確的方式展現出來。旁邊伴有高級選項的主下載控制非常易於使用。</p><h4 id="集成" tabindex="-1">集成 <a class="header-anchor" href="#集成" aria-label="Permalink to “集成”">​</a></h4><p>它能查看到剪貼板裏的URL，但uGet並沒有在本地集成到Chromium和Firefox這些瀏覽器中。儘管如此，這兩種瀏覽器還是能通過一些擴展程序連到uGet上：Firefox可以用Flashgot，Chromium則有專用的插件。雖然不是很理想，但是已經足夠好了。</p><h4 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h4><p>成熟的uGet完備了各種功能，包括按計劃啓動和終止下載任務的高級功能，通過剪貼板批量下載，還能改變它在剪貼板裏查找的文件的類型。雖然有插件選項，但不多。</p><h4 id="可獲得性" tabindex="-1">可獲得性 <a class="header-anchor" href="#可獲得性" aria-label="Permalink to “可獲得性”">​</a></h4><p>雖然在多數主要的發行版的軟件庫中都能得到它，但uGet網站上有着定期更新的適用於各種流行的發行版的二進制安裝文件，還能輕易獲得源代碼。它的運行基於GTK 3+的圖形庫，所以它在某些桌面環境上的封裝要比其他的小，然而我們得説，在KDE或其他Qt桌面上值得為此添加額外的依賴庫。</p><h4 id="總體評價" tabindex="-1">總體評價 <a class="header-anchor" href="#總體評價" aria-label="Permalink to “總體評價”">​</a></h4><p>8/10</p><p>我們非常喜歡uGet——它種類繁多的功能和極高的人氣，讓它成為了能與Linux瀏覽器優雅結合的萬能下載管理器。</p>',14)),t("h3",m,[r(l,{href:"http://bit.ly/1lilqU9"},{default:i(()=>[...a[3]||(a[3]=[e("KGet",-1)])]),_:1}),a[4]||(a[4]=e()),a[5]||(a[5]=t("a",{class:"header-anchor",href:"#kget","aria-label":"Permalink to “KGet”"},"​",-1))]),a[27]||(a[27]=n('<p>KDE自家的下載管理器貌似原本是設計成與KDE的網頁瀏覽器 Konqueror 一同工作的。它帶來了我們這次測試中所期待的功能：多下載控制和對下載完成的文件計算校驗和的能力。</p><p><img src="http://www.linuxuser.co.uk/wp-content/uploads/2014/08/kget1.png" alt="You need to manually activate the ability to keep an eye on the clipboard for links"></p><p><em>你需要手動激活查看剪貼板中下載鏈接的功能</em></p><h4 id="界面-1" tabindex="-1">界面 <a class="header-anchor" href="#界面-1" aria-label="Permalink to “界面”">​</a></h4><p>作為一個備受期待的KDE應用軟件，KGet採用一貫的圖標和線條，與桌面環境的審美風格完美融合。它的設計也相當簡潔，在主工具欄裏只顯示最必要的功能，當前下載也以最小界面顯示。</p><h4 id="集成-1" tabindex="-1">集成 <a class="header-anchor" href="#集成-1" aria-label="Permalink to “集成”">​</a></h4><p>KGet會集成到本地的KDE的Konqueror瀏覽器裏，雖然它並不是最流行的瀏覽器。Firefox對KGet的支持是一如既往的是通過FlashGot完成的，但是在Chromium裏並沒有任何一種方法能真正的將它集成進去。你可以打開一個“詢問你是否想下載已複製好的URL”的功能，然而KGet對於剪貼板的分析並不是很好，有的時候會把文本下載下來。</p><h4 id="功能-1" tabindex="-1">功能 <a class="header-anchor" href="#功能-1" aria-label="Permalink to “功能”">​</a></h4><p>能夠選擇的功能並不多。沒有計劃任務，沒有批量下載，基本上沒有什麼特色的下載功能。剪貼板掃描功能，想法很不錯就是有點問題。設置菜單看起來有點怪怪的，因為它看起來應該設計有更多的功能。</p><h4 id="可獲得性-1" tabindex="-1">可獲得性 <a class="header-anchor" href="#可獲得性-1" aria-label="Permalink to “可獲得性”">​</a></h4><p>雖然它不會隨着KDE默認安裝，但可以在任何支持KDE的發行版裏得到它。雖然它的運行需要幾個KDE庫，找到它的源代碼也很困難。除了少數幾個發行版之外也沒有什麼二進制安裝文件。</p><h4 id="總體評價-1" tabindex="-1">總體評價 <a class="header-anchor" href="#總體評價-1" aria-label="Permalink to “總體評價”">​</a></h4><p>6/10</p><p>KGet並沒有真正的給予用户比大多數主流瀏覽器內置下載管理器更強大的下載管理功能，但是，你可以在瀏覽器關閉的情況下使用它。</p>',14)),t("h3",f,[r(l,{href:"http://bit.ly/1lilqU9"},{default:i(()=>[...a[6]||(a[6]=[e("DownThemAll!",-1)])]),_:1}),a[7]||(a[7]=e()),a[8]||(a[8]=t("a",{class:"header-anchor",href:"#downthemall","aria-label":"Permalink to “DownThemAll!”"},"​",-1))]),a[28]||(a[28]=n('<p>經由Firefox的附屬組件進入Linux的DownThemAll從某種程度上可以説是跨平台。這讓它只能通過Firefox使用，然而作為世界上最流行的瀏覽器之一，它這更加緊湊的集成也許正是某些人對下載管理器所期望的。</p><p><img src="http://www.linuxuser.co.uk/wp-content/uploads/2014/08/down1.png" alt="There are actually a whole lot of options available for DownThemAll! that make it very flexible"></p><p><em>其實在DownThemALL！上有很多選項可以設置，這讓它非常的靈活</em></p><h4 id="界面-2" tabindex="-1">界面 <a class="header-anchor" href="#界面-2" aria-label="Permalink to “界面”">​</a></h4><p>與Firefox的集成使得DownThemAll！的風格符合瀏覽器的審美標準，右鍵單擊可以喚出普通下載和DownThemAll選項。額外的對話框菜單通常和Firefox的主題風格一致，然而主下載窗口則非常整潔並採用了它自己的設計。</p><h4 id="集成-2" tabindex="-1">集成 <a class="header-anchor" href="#集成-2" aria-label="Permalink to “集成”">​</a></h4><p>它並不是系統級集成，但是它偽裝在Firefox中的能力讓它看起來就像是原本瀏覽器的附加部分。如果你想，它就可以和普通下載器一同工作，在一點點手動過濾的幫助下，他還能找到網頁上特定類型的鏈接，無需複製粘貼。</p><h4 id="功能-2" tabindex="-1">功能 <a class="header-anchor" href="#功能-2" aria-label="Permalink to “功能”">​</a></h4><p>擁有着能同時控制多個下載任務的能力，限制而不浪費帶寬以及先進的自動或手動過濾功能，DownThemAll！有着一大堆有助於大規模下載的優秀功能。“一鍵”功能還讓它能非常迅速的啓動預定文件夾的下載。這比普通下載功能快多了。</p><h4 id="可獲得性-2" tabindex="-1">可獲得性 <a class="header-anchor" href="#可獲得性-2" aria-label="Permalink to “可獲得性”">​</a></h4><p>Firefox幾乎能在所有的發行版和Linux以外的操作系統中獲得。這讓DownThemAll!也和它一樣多能。不幸的是，這是一把雙刃劍，因為Firefox可能不是你喜歡的瀏覽器。它還給瀏覽器增加了一些負擔，讓它的啓動不再那麼輕鬆。</p><h4 id="總體評價-2" tabindex="-1">總體評價 <a class="header-anchor" href="#總體評價-2" aria-label="Permalink to “總體評價”">​</a></h4><p>7/10</p><p>DownThemAll!是很優秀的，如果你使用Firefox你也許就不再需要用任何其他的下載器了。然而並不是每個人都喜歡用Firefox瀏覽器，而且管理器需要在瀏覽器開啓的情況下才能啓動。</p>',14)),t("h3",x,[r(l,{href:"http://bit.ly/1lilymS"},{default:i(()=>[...a[9]||(a[9]=[e("Steadyflow",-1)])]),_:1}),a[10]||(a[10]=e()),a[11]||(a[11]=t("a",{class:"header-anchor",href:"#steadyflow","aria-label":"Permalink to “Steadyflow”"},"​",-1))]),a[29]||(a[29]=n('<p>Steadyflow很容易在Ubuntu和一些基於Debian的發行版中獲得，獲取它的方式可能受到了一些制約，但它在某些圈子裏一直被認為是你能得到的任何發行版裏最好的管理器。它能查找剪貼板裏的URL，使用GNOME的預設代理，還有許多其他的功能。</p><p><img src="http://www.linuxuser.co.uk/wp-content/uploads/2014/08/steady1.png" alt="The settings in Steady flow are extremely limiting and somewhat difficult to access"></p><p><em>Steady flow裏的設置非常少，而且有點難以使用。</em></p><h4 id="界面-3" tabindex="-1">界面 <a class="header-anchor" href="#界面-3" aria-label="Permalink to “界面”">​</a></h4><p>Steadyflow的形象相當簡潔，令人愉悦的、乾淨的界面並沒有讓下載窗口變得混亂。添加下載任務的對話框足夠簡潔，只有基本的選項來設置下載任務，設置文件位置。真沒什麼可抱怨的，雖然它的確讓我們覺得它的功能有點少。</p><h4 id="集成-3" tabindex="-1">集成 <a class="header-anchor" href="#集成-3" aria-label="Permalink to “集成”">​</a></h4><p>查看複製的URL是標準配備，還有個讓Chromium集成這個功能的插件。同樣的，如果你喜歡用Firefox你可以通過Flashgot把它連到Firefox上。你並不能真正的編輯它從剪貼板裏分析出的鏈接，它也不能像uGet和DownThemAll!一樣批量下載。</p><h4 id="功能-3" tabindex="-1">功能 <a class="header-anchor" href="#功能-3" aria-label="Permalink to “功能”">​</a></h4><p>極度缺少功能，選項菜單也受到很大限制。暫停和恢復功能看起來也不怎麼好使——這是任何瀏覽器文件下載功能的最基本的部分。文件下載結束的通知和默認行為是可以設置的，還可以選擇在文件下載完成之後運行腳本。</p><h4 id="可獲得性-3" tabindex="-1">可獲得性 <a class="header-anchor" href="#可獲得性-3" aria-label="Permalink to “可獲得性”">​</a></h4><p>只能在Ubuntu上獲取，還不容易得到這個應用的源代碼。這意味着雖然在所有基於Ubuntu的發行版中都能很容易的得到它，但也僅限於這些發行版。由於它不是Linux上能得到的最好的下載管理器，所以也不用想太多。</p><h4 id="總體評價-3" tabindex="-1">總體評價 <a class="header-anchor" href="#總體評價-3" aria-label="Permalink to “總體評價”">​</a></h4><p>5/10</p><p>坦白説，沒那麼好。只有非常基本的選項，還只能在Ubuntu上使用，Steadyflow要想從你能選擇的瀏覽器自帶的標準下載選項中脱穎而出，它做的還不夠。</p><h3 id="那麼獲獎者是" tabindex="-1">那麼獲獎者是…… <a class="header-anchor" href="#那麼獲獎者是" aria-label="Permalink to “那麼獲獎者是……”">​</a></h3><h4 id="uget-1" tabindex="-1">uGet <a class="header-anchor" href="#uget-1" aria-label="Permalink to “uGet”">​</a></h4><p>在此次測試中，我們已經證明了現代電腦中還是有下載管理器的一席之地的，即便它們中的佼佼者們從BT下載客户端中抄襲了某些功能，貌似侵犯了他們的權益。對於某些人來説BT下載可能是個更有效率的方式，隨着ISP們對待BT流量越來越機智，一些人可能用一個好的下載管理器就得到更好的效果。大多數主流ISP不僅僅強加了數據傳輸限額，在高峯時段他們中的一些甚至開始減慢或封掉BT流量——甚至連發行版的ISO文件和其他免費軟件的合法數據流都被限制了。</p><p>對於這類問題Steadyflow看起來是非常受歡迎的解決方式，但我們的使用和測試顯示出，它是一個未完成的簡陋的產品。更加古老的uGet則是這場表演的明星，有着驚人數量的可選功能，這些功能既能在下載單一文件中有所幫助，還能在整個網頁裏過濾出相關元素進行抓取。DownThemAll！與之類似，優秀的Firefox有加分，但它也離不開Firefox，有着幾乎同級別的功能，但集成效果更好。</p><p>如果你要在這兩個裏面選一個，那就得談談你喜歡哪個瀏覽器還有你是否需要晝夜下載或上傳文件。DownThemAll!需要Firefox一直運行，然而uGet可以單獨運行，為處理器節省了很多資源和電力——這顯然讓uGet在24小時數據傳輸上顯得更有前途，而且對於它來説，設置一大批下載任務或只是從你的瀏覽器中獲取下載信息，都不是什麼難事。</p><p>再給下載管理器一個機會。結果絕不會讓你失望。</p><hr>',21)),t("p",null,[a[13]||(a[13]=e("via: ",-1)),r(l,{href:"http://www.linuxuser.co.uk/reviews/top-4-linux-download-managers"},{default:i(()=>[...a[12]||(a[12]=[e("http://www.linuxuser.co.uk/reviews/top-4-linux-download-managers",-1)])]),_:1})]),t("p",null,[a[16]||(a[16]=e("作者：Rob Zwetsloot 譯者：",-1)),r(l,{href:"https://github.com/H-mudcup"},{default:i(()=>[...a[14]||(a[14]=[e("H-mudcup",-1)])]),_:1}),a[17]||(a[17]=e(" 校對：",-1)),r(l,{href:"https://github.com/wxy"},{default:i(()=>[...a[15]||(a[15]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[20]||(a[20]=e("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[18]||(a[18]=[e("LCTT",-1)])]),_:1}),a[21]||(a[21]=e(" 原創翻譯，",-1)),r(l,{href:"http://linux.cn/"},{default:i(()=>[...a[19]||(a[19]=[e("Linux中國",-1)])]),_:1}),a[22]||(a[22]=e(" 榮譽推出",-1))])])}const y=o(h,[["render",b]]);export{G as __pageData,y as default};
